<script setup lang="ts">
import { ref, watch, computed } from 'vue'
import type { DocumentSheet, FooterCell } from '@/lib/types/documents'
const props = defineProps<{ footers?: FooterCell[] }>()
const summary = defineModel<DocumentSheet | null>({ required: true }), text = ref(''), error = ref('')
const totals = computed(() => summary.value?.totals as { sum: string[]; blankBordered: string[] } | undefined)
function create() { summary.value = { name: 'خلاصه', role: 'summary', startCol: 'D', title: { fromCol: 'C', toCol: 'H', expr: '"خلاصه"', style: 'title' }, columns: (props.footers ?? []).filter(f => f.agg).map(f => ({ key: `summary_${f.id}`, label: f.id, from: `footer:${f.id}` })), headerStyle: 'header', rowStyle: 'cell', equalsRow: true, totals: { sum: (props.footers ?? []).filter(f => f.agg).map(f => f.id), blankBordered: [] } } }
function toggle(id: string) { if (!totals.value) return; totals.value.sum = totals.value.sum.includes(id) ? totals.value.sum.filter(x => x !== id) : [...totals.value.sum, id] }
watch(summary, value => { text.value = value ? JSON.stringify(value, null, 2) : '' }, { immediate: true })
function apply() { try { summary.value = text.value.trim() ? JSON.parse(text.value) as DocumentSheet : null; error.value = '' } catch { error.value = 'ساختار خلاصه درست نیست؛ پرانتزها و ویرگول‌ها را بررسی کنید.' } }
</script>
<template><details class="rounded-lg border border-outline-variant p-3"><summary class="min-h-11 cursor-pointer font-bold">خلاصهٔ آخر سند</summary><p class="py-2">هر ستون خلاصه به یکی از جمع‌های پایین بسته وصل می‌شود.</p><button v-if="!summary" class="min-h-11 px-4 text-primary" @click="create">افزودن برگهٔ خلاصه</button><div v-else class="space-y-3"><label class="block">نام برگه<input v-model="summary.name" class="min-h-11 w-full rounded border border-outline-variant bg-surface p-2" /></label><label v-if="summary.title" class="block">عبارت عنوان<textarea v-model="summary.title.expr" dir="ltr" class="min-h-20 w-full rounded border border-outline-variant bg-surface p-2" /></label><div v-for="(column, i) in summary.columns" :key="i" class="grid gap-2 rounded bg-surface-container p-3 sm:grid-cols-3"><label>عنوان<input v-model="column.label" class="min-h-11 w-full rounded border border-outline-variant bg-surface p-2" /></label><label>جمع مرجع<select v-model="column.from" class="min-h-11 w-full rounded border border-outline-variant bg-surface p-2"><option v-for="f in footers" :key="f.id" :value="`footer:${f.id}`">{{ f.id }}</option></select></label><button class="min-h-11 text-error" @click="summary.columns.splice(i,1)">حذف ستون خلاصه</button></div><button class="min-h-11 px-4 text-primary" @click="summary.columns.push({ key: `summary${summary.columns.length}`,label:'جمع',from:`footer:${footers?.[0]?.id ?? ''}` })">افزودن ستون خلاصه</button><div v-if="totals"><p>جمع نهایی این ستون‌ها:</p><label v-for="f in footers" :key="f.id" class="inline-flex min-h-11 items-center gap-2 px-3"><input type="checkbox" :checked="totals.sum.includes(f.id)" @change="toggle(f.id)" />{{ f.id }}</label></div><label class="flex min-h-11 items-center gap-2"><input v-model="summary.equalsRow" type="checkbox" />ردیف علامت مساوی</label><button class="min-h-11 px-4 text-error" @click="summary = null">حذف برگهٔ خلاصه</button></div><details class="mt-3"><summary class="min-h-11 cursor-pointer">ساختار پیشرفتهٔ خلاصه</summary><textarea v-model="text" dir="ltr" aria-label="ساختار خلاصه" class="min-h-64 w-full rounded border border-outline-variant bg-surface p-3 font-mono" /><button class="min-h-11 px-4 text-primary" @click="apply">اعمال ساختار</button></details><p v-if="error" role="alert" class="text-error">{{ error }}</p></details></template>
